struct FilesystemControl {
    physical_root: std::path::PathBuf,
    trusted_source_root: std::path::PathBuf,
}
impl Drop for FilesystemControl {
    fn drop(&mut self) {
        let _ = fs::remove_dir_all(&self.physical_root);
    }
}
